```python
from dataclasses import dataclass


@dataclass(frozen=True)
class Product:
    name: str
    price_cents: int

    def __post_init__(self):
        if not isinstance(self.price_cents, int) or self.price_cents < 0:
            raise ValueError("Price must be a non-negative integer number of cents")


@dataclass(frozen=True)
class Discount:
    # Either a fixed amount in cents or a percentage in basis points.
    kind: str
    value: int

    def __post_init__(self):
        if self.kind not in ("fixed", "percent"):
            raise ValueError("Unknown discount kind")
        if not isinstance(self.value, int) or self.value < 0:
            raise ValueError("Discount value must be a non-negative integer")
        if self.kind == "percent" and self.value > 10_000:
            raise ValueError("Percentage cannot exceed 100%")


DISCOUNTS = {
    "SAVE5": Discount("fixed", 500),       # $5.00 off
    "TENPERCENT": Discount("percent", 1000),  # 10% off
}


class ShoppingCart:
    def __init__(self):
        self._items = []
        self._discounts = []
        self._applied_codes = set()

    def add_product(self, product: Product, quantity: int):
        if not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("Quantity must be a positive integer")
        self._items.append((product, quantity))

    def apply_discount(self, code: str):
        code = code.strip().upper()

        if code in self._applied_codes:
            raise ValueError("Discount code has already been applied")
        if code not in DISCOUNTS:
            raise ValueError("Invalid discount code")

        self._applied_codes.add(code)
        self._discounts.append(DISCOUNTS[code])

    def final_price_cents(self) -> int:
        total = sum(product.price_cents * quantity
                    for product, quantity in self._items)

        # Apply discounts in the order entered.
        for discount in self._discounts:
            if discount.kind == "fixed":
                amount = discount.value
            else:
                # Round the discount to the nearest cent, with halves rounded up.
                amount = (total * discount.value + 5_000) // 10_000
            total = max(0, total - amount)

        return total


cart = ShoppingCart()
cart.add_product(Product("Notebook", 1250), 2)
cart.apply_discount("TENPERCENT")
cart.apply_discount("SAVE5")

cents = cart.final_price_cents()
print(f"${cents // 100}.{cents % 100:02d}")  # $17.50
```

Discounts are applied in entry order, so changing their order can change the final price.

